// TypeScript Version: 4.1

/// <reference types="@stdlib/types"/>

import { Order, Mode, genericndarray, Shape2D } from '@stdlib/types/ndarray';
import { Collection, AccessorArrayLike, ArrayLike } from '@stdlib/types/array';

/**
* Interface describing function options.
*/
interface Options {
	/**
	* Array order (either 'row-major' (C-style) or 'column-major' (Fortran-style)).
	*/
	order?: Order;

	/**
	* Specifies how to handle a linear index which exceeds array dimensions (default: 'throw').
	*/
	mode?: Mode;

	/**
	* Specifies how to handle subscripts which exceed array dimensions on a per dimension basis (default: ['throw']).
	*/
	submode?: ArrayLike<Mode>;

	/**
	* Boolean indicating whether an array should be read-only (default: false).
	*/
	readonly?: boolean;
}

/**
* Interface defining a typed matrix constructor which is both "newable" and "callable".
*/
interface GenericMatrix {
	/**
	* Creates a "generic" matrix (i.e., a two-dimensional ndarray).
	*
	* @param options - function options
	* @param options.readonly - boolean indicating whether to return a read-only matrix
	* @param options.mode - specifies how to handle indices which exceed matrix dimensions
	* @param options.submode - specifies how to handle subscripts which exceed array dimensions on a per dimension basis
	* @param options.order - memory layout (either row-major or column-major)
	* @returns two-dimensional ndarray
	*
	* @example
	* var getShape = require( '@stdlib/ndarray/shape' );
	*
	* var arr = new GenericMatrix();
	* // returns <ndarray>
	*
	* var sh = getShape( arr );
	* // returns [ 0, 0 ]
	*/
	new ( options?: Options ): genericndarray<unknown>;

	/**
	* Creates a "generic" matrix (i.e., a two-dimensional ndarray).
	*
	* @param shape - matrix shape
	* @param options - function options
	* @param options.readonly - boolean indicating whether to return a read-only matrix
	* @param options.mode - specifies how to handle indices which exceed matrix dimensions
	* @param options.submode - specifies how to handle subscripts which exceed array dimensions on a per dimension basis
	* @param options.order - memory layout (either row-major or column-major)
	* @returns two-dimensional ndarray
	*
	* @example
	* var getShape = require( '@stdlib/ndarray/shape' );
	*
	* var arr = new GenericMatrix( [ 2, 2 ] );
	* // returns <ndarray>
	*
	* var sh = getShape( arr );
	* // returns [ 2, 2 ]
	*/
	new ( shape: Shape2D, options?: Options ): genericndarray<unknown>;

	/**
	* Creates a "generic" matrix (i.e., a two-dimensional ndarray).
	*
	* @param M - number of rows
	* @param N - number of columns
	* @param options - function options
	* @param options.readonly - boolean indicating whether to return a read-only matrix
	* @param options.mode - specifies how to handle indices which exceed matrix dimensions
	* @param options.submode - specifies how to handle subscripts which exceed array dimensions on a per dimension basis
	* @param options.order - memory layout (either row-major or column-major)
	* @returns two-dimensional ndarray
	*
	* @example
	* var getShape = require( '@stdlib/ndarray/shape' );
	*
	* var arr = new GenericMatrix( 2, 2 );
	* // returns <ndarray>
	*
	* var sh = getShape( arr );
	* // returns [ 2, 2 ]
	*/
	new ( M: number, N: number, options?: Options ): genericndarray<unknown>;

	/**
	* Creates a "generic" matrix (i.e., a two-dimensional ndarray).
	*
	* @param obj - array-like object or iterable from which to generate a matrix
	* @param options - function options
	* @param options.readonly - boolean indicating whether to return a read-only matrix
	* @param options.mode - specifies how to handle indices which exceed matrix dimensions
	* @param options.submode - specifies how to handle subscripts which exceed array dimensions on a per dimension basis
	* @param options.order - memory layout (either row-major or column-major)
	* @returns two-dimensional ndarray
	*
	* @example
	* var getShape = require( '@stdlib/ndarray/shape' );
	*
	* var arr = new GenericMatrix( [ [ 1.0, 2.0 ], [ 3.0, 4.0 ] ] );
	* // returns <ndarray>
	*
	* var sh = getShape( arr );
	* // returns [ 2, 2 ]
	*/
	new <T = unknown>( obj: ArrayLike<Collection<T> | AccessorArrayLike<T>> | Iterable<Collection<T> | AccessorArrayLike<T>>, options?: Options ): genericndarray<T>;

	/**
	* Creates a "generic" matrix (i.e., a two-dimensional ndarray).
	*
	* @param options - function options
	* @param options.readonly - boolean indicating whether to return a read-only matrix
	* @param options.mode - specifies how to handle indices which exceed matrix dimensions
	* @param options.submode - specifies how to handle subscripts which exceed array dimensions on a per dimension basis
	* @param options.order - memory layout (either row-major or column-major)
	* @returns two-dimensional ndarray
	*
	* @example
	* var getShape = require( '@stdlib/ndarray/shape' );
	*
	* var arr = new GenericMatrix();
	* // returns <ndarray>
	*
	* var sh = getShape( arr );
	* // returns [ 0, 0 ]
	*/
	( options?: Options ): genericndarray<unknown>;

	/**
	* Creates a "generic" matrix (i.e., a two-dimensional ndarray).
	*
	* @param shape - matrix shape
	* @param options - function options
	* @param options.readonly - boolean indicating whether to return a read-only matrix
	* @param options.mode - specifies how to handle indices which exceed matrix dimensions
	* @param options.submode - specifies how to handle subscripts which exceed array dimensions on a per dimension basis
	* @param options.order - memory layout (either row-major or column-major)
	* @returns two-dimensional ndarray
	*
	* @example
	* var getShape = require( '@stdlib/ndarray/shape' );
	*
	* var arr = new GenericMatrix( [ 2, 2 ] );
	* // returns <ndarray>
	*
	* var sh = getShape( arr );
	* // returns [ 2, 2 ]
	*/
	( shape: Shape2D, options?: Options ): genericndarray<unknown>;

	/**
	* Creates a "generic" matrix (i.e., a two-dimensional ndarray).
	*
	* @param M - number of rows
	* @param N - number of columns
	* @param options - function options
	* @param options.readonly - boolean indicating whether to return a read-only matrix
	* @param options.mode - specifies how to handle indices which exceed matrix dimensions
	* @param options.submode - specifies how to handle subscripts which exceed array dimensions on a per dimension basis
	* @param options.order - memory layout (either row-major or column-major)
	* @returns two-dimensional ndarray
	*
	* @example
	* var getShape = require( '@stdlib/ndarray/shape' );
	*
	* var arr = new GenericMatrix( 2, 2 );
	* // returns <ndarray>
	*
	* var sh = getShape( arr );
	* // returns [ 2, 2 ]
	*/
	( M: number, N: number, options?: Options ): genericndarray<unknown>;

	/**
	* Creates a "generic" matrix (i.e., a two-dimensional ndarray).
	*
	* @param obj - array-like object or iterable from which to generate a matrix
	* @param options - function options
	* @param options.readonly - boolean indicating whether to return a read-only matrix
	* @param options.mode - specifies how to handle indices which exceed matrix dimensions
	* @param options.submode - specifies how to handle subscripts which exceed array dimensions on a per dimension basis
	* @param options.order - memory layout (either row-major or column-major)
	* @returns two-dimensional ndarray
	*
	* @example
	* var getShape = require( '@stdlib/ndarray/shape' );
	*
	* var arr = new GenericMatrix( [ [ 1.0, 2.0 ], [ 3.0, 4.0 ] ] );
	* // returns <ndarray>
	*
	* var sh = getShape( arr );
	* // returns [ 2, 2 ]
	*/
	<T = unknown>( obj: ArrayLike<Collection<T> | AccessorArrayLike<T>> | Iterable<Collection<T> | AccessorArrayLike<T>>, options?: Options ): genericndarray<T>;
}

/**
* Creates a "generic" matrix (i.e., a two-dimensional ndarray).
*
* @param arg0 - shape, number of rows, array-like object, or iterable
* @param arg1 - number of columns
* @param options - function options
* @param options.readonly - boolean indicating whether to return a read-only matrix
* @param options.mode - specifies how to handle indices which exceed matrix dimensions
* @param options.submode - specifies how to handle subscripts which exceed array dimensions on a per dimension basis
* @param options.order - memory layout (either row-major or column-major)
* @returns two-dimensional ndarray
*
* @example
* var getShape = require( '@stdlib/ndarray/shape' );
*
* var arr = new GenericMatrix();
* // returns <ndarray>
*
* var sh = getShape( arr );
* // returns [ 0, 0 ]
*
* @example
* var getShape = require( '@stdlib/ndarray/shape' );
*
* var arr = new GenericMatrix( [ 2, 2 ] );
* // returns <ndarray>
*
* var sh = getShape( arr );
* // returns [ 2, 2 ]
*
* @example
* var getShape = require( '@stdlib/ndarray/shape' );
*
* var arr = new GenericMatrix( 2, 2 );
* // returns <ndarray>
*
* var sh = getShape( arr );
* // returns [ 2, 2 ]
*
* @example
* var getShape = require( '@stdlib/ndarray/shape' );
*
* var arr = new GenericMatrix( [ [ 1.0, 2.0 ], [ 3.0, 4.0 ] ] );
* // returns <ndarray>
*
* var sh = getShape( arr );
* // returns [ 2, 2 ]
*/
declare var ctor: GenericMatrix;


// EXPORTS //

export = ctor;
